1	// Small text helpers shared across the command renderers (list, doctor).
2	// Header-only; no dependencies beyond the standard library.
3	#ifndef ANDES_SIM_STRUTIL_HPP
4	#define ANDES_SIM_STRUTIL_HPP
5	
6	#include <string>
7	#include <vector>
8	
9	namespace andes_sim {
10	
11	// Left-justify `s` to width `w` (pad with spaces; never truncate).
12	inline std::string ljust(std::string s, size_t w) {
13	  if (s.size() < w) s.append(w - s.size(), ' ');
14	  return s;
15	}
16	
17	// Join `v` with `sep` between elements.
18	inline std::string join(const std::vector<std::string>& v, const char* sep = ",") {
19	  std::string s;
20	  for (size_t k = 0; k < v.size(); ++k) {
21	    if (k) s += sep;
22	    s += v[k];
23	  }
24	  return s;
25	}
26	
27	// Engine VLEN for display: a positive width prints as its number, 0/absent "-".
28	inline std::string vlen_str(long v) {
29	  return v > 0 ? std::to_string(v) : std::string("-");
30	}
31	
32	}  // namespace andes_sim
33	
34	#endif  // ANDES_SIM_STRUTIL_HPP
