1	#include "process.hpp"
2	
3	#include <cerrno>
4	#include <ctime>
5	
6	#include <fcntl.h>
7	#include <poll.h>
8	#include <signal.h>
9	#include <sys/wait.h>
10	#include <unistd.h>
11	
12	namespace andes_sim {
13	namespace {
14	
15	long now_ms() {
16	  struct timespec ts;
17	  clock_gettime(CLOCK_MONOTONIC, &ts);
18	  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
19	}
20	
21	// fork + (optional chdir) + (optional stdin from /dev/null) + exec + wait. The
22	// child always inherits this process's stdout and stderr. Returns the child's
23	// exit code, 128+signal if it was signalled, or -1 on empty argv / fork
24	// failure. Backs both run_inherit (build: stdin closed, chdir) and
25	// exec_passthrough (run fast/accurate: stdin inherited, no chdir).
26	int spawn_inherit(const std::vector<std::string>& argv, const std::string& cwd,
27	                  bool stdin_from_devnull) {
28	  if (argv.empty()) return -1;
29	
30	  pid_t pid = fork();
31	  if (pid < 0) return -1;
32	
33	  if (pid == 0) {  // child
34	    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
35	    if (stdin_from_devnull) {
36	      int devnull = open("/dev/null", O_RDONLY);
37	      if (devnull >= 0) {
38	        dup2(devnull, STDIN_FILENO);
39	        if (devnull > 2) close(devnull);
40	      }
41	    }
42	    std::vector<char*> cargv;
43	    cargv.reserve(argv.size() + 1);
44	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
45	    cargv.push_back(nullptr);
46	    execvp(cargv[0], cargv.data());
47	    _exit(127);  // exec failed
48	  }
49	
50	  int status = 0;
51	  waitpid(pid, &status, 0);
52	  if (WIFEXITED(status)) return WEXITSTATUS(status);
53	  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
54	  return -1;
55	}
56	
57	}  // namespace
58	
59	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
60	  RunResult r;
61	  if (argv.empty()) {
62	    r.spawn_failed = true;
63	    return r;
64	  }
65	
66	  int fds[2];
67	  if (pipe(fds) != 0) {
68	    r.spawn_failed = true;
69	    return r;
70	  }
71	
72	  pid_t pid = fork();
73	  if (pid < 0) {
74	    close(fds[0]);
75	    close(fds[1]);
76	    r.spawn_failed = true;
77	    return r;
78	  }
79	
80	  if (pid == 0) {  // child
81	    close(fds[0]);
82	    dup2(fds[1], STDOUT_FILENO);
83	    int devnull = open("/dev/null", O_RDWR);
84	    if (devnull >= 0) {
85	      dup2(devnull, STDIN_FILENO);
86	      dup2(devnull, STDERR_FILENO);
87	      if (devnull > 2) close(devnull);
88	    }
89	    close(fds[1]);
90	    std::vector<char*> cargv;
91	    cargv.reserve(argv.size() + 1);
92	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
93	    cargv.push_back(nullptr);
94	    execvp(cargv[0], cargv.data());
95	    _exit(127);  // exec failed
96	  }
97	
98	  // parent
99	  close(fds[1]);
100	  int rfd = fds[0];
101	  const long deadline = now_ms() + timeout_ms;
102	  char buf[4096];
103	
104	  while (true) {
105	    long remaining = deadline - now_ms();
106	    if (remaining < 0) remaining = 0;
107	    struct pollfd pfd{rfd, POLLIN, 0};
108	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
109	    if (pr < 0) {
110	      if (errno == EINTR) continue;
111	      break;
112	    }
113	    if (pr == 0) {  // timed out with no data ready
114	      kill(pid, SIGKILL);
115	      r.timed_out = true;
116	      break;
117	    }
118	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
119	      ssize_t n = read(rfd, buf, sizeof(buf));
120	      if (n > 0) {
121	        r.out.append(buf, static_cast<size_t>(n));
122	      } else if (n == 0) {
123	        break;  // EOF: child closed stdout
124	      } else {
125	        if (errno == EINTR) continue;
126	        break;
127	      }
128	    }
129	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
130	      kill(pid, SIGKILL);
131	      r.timed_out = true;
132	      break;
133	    }
134	  }
135	
136	  close(rfd);
137	  int status = 0;
138	  waitpid(pid, &status, 0);
139	  // rc stays -1 (the default) when timed out or abnormally terminated.
140	  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
141	  return r;
142	}
143	
144	int run_inherit(const std::vector<std::string>& argv, const std::string& cwd) {
145	  return spawn_inherit(argv, cwd, /*stdin_from_devnull=*/true);
146	}
147	
148	int exec_passthrough(const std::vector<std::string>& argv) {
149	  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false);
150	}
151	
152	}  // namespace andes_sim
