1	// Unit tests for the F5 infra helpers:
2	//   - parse_size          (driver/shm.hpp)   size-spec parsing
3	//   - exec_passthrough    (driver/process.hpp) exit-code propagation
4	//   - run_process         (driver/process.hpp) timeout kill + capture
5	//   - read_state_file     (driver/state.hpp)  hybrid_state_v1 read + validate
6	//
7	// Plain assert-and-count harness (no doctest); each CHECK bumps a failure
8	// counter and the process exits non-zero if any failed. Run by
9	// tests/andes_sim/test_andes_sim_f5.sh.
10	#include <cstdint>
11	#include <cstdlib>
12	#include <string>
13	#include <vector>
14	
15	#include <fcntl.h>
16	#include <unistd.h>
17	
18	#include "hybrid/state_abi.h"
19	#include "process.hpp"
20	#include "shm.hpp"
21	#include "state.hpp"
22	#include "test_check.hpp"
23	
24	using namespace andes_sim;
25	
26	int main() {
27	  // --- parse_size: <number>[K|M|G|T] -> byte count ---
28	  {
29	    std::string err;
30	    CHECK(parse_size("1024", err) == 1024 && err.empty());
31	    CHECK(parse_size("128M", err) == 128LL * 1024 * 1024);
32	    CHECK(parse_size("512M", err) == 512LL * 1024 * 1024);
33	    CHECK(parse_size("8G", err) == 8LL * 1024 * 1024 * 1024);
34	    CHECK(parse_size("1T", err) == 1LL * 1024 * 1024 * 1024 * 1024);
35	    // fractional value truncates like Python int(float(num) * mult)
36	    CHECK(parse_size("1.5G", err) ==
37	          static_cast<long long>(1.5 * 1024 * 1024 * 1024));
38	    // suffix is case-insensitive and surrounding whitespace is tolerated
39	    CHECK(parse_size("  64m  ", err) == 64LL * 1024 * 1024);
40	    // malformed specs return 0 and set err
41	    for (const char* bad : {"", "8X", "0", "abc", "-4", "1.2.3"}) {
42	      err.clear();
43	      CHECK(parse_size(bad, err) == 0 && !err.empty());
44	    }
45	  }
46	
47	  // --- exec_passthrough: forwards the child's exit code ---
48	  {
49	    CHECK(exec_passthrough({"sh", "-c", "exit 0"}) == 0);
50	    CHECK(exec_passthrough({"sh", "-c", "exit 7"}) == 7);
51	    CHECK(exec_passthrough({"sh", "-c", "exit 42"}) == 42);
52	    // a binary that cannot be exec'd reports 127 (exec failure)
53	    CHECK(exec_passthrough({"/nonexistent/andes-sim-xyz"}) == 127);
54	    // empty argv: nothing to run
55	    CHECK(exec_passthrough({}) == -1);
56	  }
57	
58	  // --- run_process: a slow child is killed at the timeout ---
59	  {
60	    RunResult r = run_process({"sh", "-c", "sleep 5"}, 150);
61	    CHECK(r.timed_out);
62	    CHECK(r.rc == -1);
63	  }
64	  // --- run_process: a fast child's stdout is captured and rc propagated ---
65	  {
66	    RunResult r = run_process({"sh", "-c", "printf hello; exit 3"}, 2000);
67	    CHECK(!r.timed_out);
68	    CHECK(r.rc == 3);
69	    CHECK(r.out == "hello");
70	  }
71	
72	  // --- read_state_file: round-trip a known-good hybrid_state_v1 ---
73	  {
74	    hybrid_state_v1 st{};
75	    st.magic = HYBRID_STATE_MAGIC;
76	    st.version = HYBRID_STATE_VERSION;
77	    st.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
78	    st.mcycle = 123456;
79	    st.minstret = 7890;
80	    st.vlenb = 64;
81	
82	    char path[] = "/tmp/andes-sim-state.XXXXXX";
83	    int fd = mkstemp(path);
84	    CHECK(fd >= 0);
85	    CHECK(write(fd, &st, sizeof(st)) == static_cast<ssize_t>(sizeof(st)));
86	    close(fd);
87	
88	    StateFile good = read_state_file(path);
89	    CHECK(good.ok());
90	    CHECK(good.error.empty());
91	    CHECK(good.st.mcycle == 123456);
92	    CHECK(good.st.minstret == 7890);
93	    CHECK(good.st.flags == (HYBRID_FLAG_RV64 | HYBRID_FLAG_V));
94	    CHECK(good.st.vlenb == 64);
95	
96	    // a bad magic is rejected
97	    st.magic = 0xdeadbeefu;
98	    int fd2 = open(path, O_WRONLY | O_TRUNC);
99	    CHECK(fd2 >= 0);
100	    CHECK(write(fd2, &st, sizeof(st)) == static_cast<ssize_t>(sizeof(st)));
101	    close(fd2);
102	    CHECK(!read_state_file(path).ok());
103	
104	    // a truncated file (wrong size) is rejected
105	    st.magic = HYBRID_STATE_MAGIC;
106	    int fd3 = open(path, O_WRONLY | O_TRUNC);
107	    CHECK(fd3 >= 0);
108	    CHECK(write(fd3, &st, 16) == 16);
109	    close(fd3);
110	    CHECK(!read_state_file(path).ok());
111	
112	    unlink(path);
113	  }
114	  // a missing file is rejected (not a crash)
115	  CHECK(!read_state_file("/nonexistent/andes-sim-no-such-state").ok());
116	
117	  return andes_sim::test::report("infra");
118	}
