1	// Repo-root discovery for andes-sim.
2	//
3	// The driver shells out to repo scripts (scripts/build_*.sh), reads fixtures
4	// (tests/fixtures/), and scans the engines dir -- all relative to the repo
5	// root. The root is found from the executable's own location via
6	// /proc/self/exe, so it works regardless of the caller's CWD and for both
7	// layouts: build/andes-sim during development and a repo-root andes-sim after
8	// the F14 swap.
9	#ifndef ANDES_SIM_REPO_ROOT_HPP
10	#define ANDES_SIM_REPO_ROOT_HPP
11	
12	#include <climits>
13	#include <filesystem>
14	#include <stdexcept>
15	#include <string>
16	
17	#include <unistd.h>
18	
19	namespace andes_sim {
20	
21	// Absolute path to this executable, resolved through /proc/self/exe.
22	inline std::filesystem::path exe_path() {
23	  char buf[PATH_MAX];
24	  ssize_t n = ::readlink("/proc/self/exe", buf, sizeof(buf) - 1);
25	  if (n < 0) throw std::runtime_error("readlink(/proc/self/exe) failed");
26	  buf[n] = '\0';
27	  return std::filesystem::path(buf);
28	}
29	
30	// Nearest ancestor of the executable that looks like this repo's root,
31	// identified by two stable markers that travel together: the setup.sh build
32	// entry point and the shared ABI header. Throws if no such ancestor exists.
33	inline std::filesystem::path repo_root() {
34	  namespace fs = std::filesystem;
35	  // Pure function of /proc/self/exe and the on-disk layout, both stable for the
36	  // life of the process, so compute it once. (If discovery fails the throwing
37	  // initializer just re-runs on the next call.)
38	  static const fs::path root = [] {
39	    fs::path start = exe_path().parent_path();
40	    for (fs::path p = start;; p = p.parent_path()) {
41	      if (fs::exists(p / "setup.sh") &&
42	          fs::exists(p / "include" / "hybrid" / "state_abi.h"))
43	        return p;
44	      if (p == p.root_path()) break;
45	    }
46	    throw std::runtime_error("repo root not found above " + start.string());
47	  }();
48	  return root;
49	}
50	
51	}  // namespace andes_sim
52	
53	#endif  // ANDES_SIM_REPO_ROOT_HPP
54

